//! The library (`src/library`): files arriving over tus, checked rather than
//! trusted, served in ranges, drawn as thumbnails, kept while a project uses
//! them — and none of it reachable by another user.
//!
//! Real media, generated by ffmpeg through the command builder, because what
//! is under test includes probing it.

#[path = "../common/mod.rs"]
mod common;

mod files;
mod generated;
mod manage;
mod upload;

use std::net::SocketAddr;
use std::path::Path;

use common::{Response, send};
use scorsese_core::hash_bytes;
use scorsese_server::accounts::{sessions, users};
use scorsese_server::db::UserId;
use sqlx::postgres::PgPool;

/// A new account and its browser's `Cookie:` line.
async fn member(pool: &PgPool, email: &str) -> (UserId, String) {
    let user = users::create(pool, email, "password one")
        .await
        .expect("the account is created");
    let cookie = sessions::open(pool, user).await.expect("a session opens");
    (user, format!("Cookie: scorsese_session={cookie}"))
}

/// A one-second 64×64 video with a tone, made by ffmpeg under `directory`.
fn video(directory: &Path) -> Vec<u8> {
    let file = directory.join("fixture.mp4");
    let output = common::tools()
        .ffmpeg()
        .args(["-v", "error", "-y", "-f", "lavfi", "-i"])
        .arg("testsrc=s=64x64:d=1:r=30")
        .args(["-f", "lavfi", "-i", "sine=duration=1", "-shortest"])
        .args(["-pix_fmt", "yuv420p"])
        .arg(&file)
        .output()
        .expect("ffmpeg runs");
    assert!(output.status.success(), "{output:?}");
    std::fs::read(file).expect("the fixture reads")
}

/// Announce `bytes` as `name` for the member `who`: the tus creation request.
async fn announce(address: SocketAddr, who: &str, name: &str, bytes: &[u8]) -> Response {
    announce_as(address, who, name, &hash_bytes(bytes), bytes.len()).await
}

/// Announce a file claiming to be `sha256`, `length` bytes long.
async fn announce_as(
    address: SocketAddr,
    who: &str,
    name: &str,
    sha256: &str,
    length: usize,
) -> Response {
    use base64::Engine;
    let encode = |text: &str| base64::engine::general_purpose::STANDARD.encode(text);
    let metadata = format!(
        "Upload-Metadata: filename {},sha256 {}",
        encode(name),
        encode(sha256)
    );
    let length = format!("Upload-Length: {length}");
    let headers = [who, "Tus-Resumable: 1.0.0", &length, &metadata];
    send(address, "POST", "/api/uploads", &headers, &[]).await
}

/// Send `bytes` to the upload at `location`, starting at `offset`.
async fn patch(
    address: SocketAddr,
    who: &str,
    location: &str,
    offset: usize,
    bytes: &[u8],
) -> Response {
    let offset = format!("Upload-Offset: {offset}");
    let headers = [
        who,
        "Tus-Resumable: 1.0.0",
        "Content-Type: application/offset+octet-stream",
        &offset,
    ];
    send(address, "PATCH", location, &headers, bytes).await
}

/// Upload `bytes` as `name` whole, in two chunks; the new item's id.
async fn upload(address: SocketAddr, who: &str, name: &str, bytes: &[u8]) -> i64 {
    let created = announce(address, who, name, bytes).await;
    assert_eq!(created.status, 201, "{}", created.body);
    let location = created.header("location").expect("a Location").to_owned();
    let half = bytes.len() / 2;
    let first = patch(address, who, &location, 0, &bytes[..half]).await;
    assert_eq!(first.status, 204, "{}", first.body);
    let last = patch(address, who, &location, half, &bytes[half..]).await;
    assert_eq!(last.status, 204, "{}", last.body);
    last.header("scorsese-library-item")
        .and_then(|id| id.parse().ok())
        .expect("the last chunk names the item")
}
